import {expect,test} from '@playwright/test';
// P12.3: 25 standard progressions, in the order of the grouped list (spec appendix B), by their display name.
const STANDARD_NAMES=['ii–V–I','I–V–vi–IV','循環進行','3-6-2-5-1','I–VI7–ii–V','IV–iii–ii–I','王道進行','小室進行','丸サ進行','カノン進行','IV–III7–vi','サブドミナントマイナー','裏コード','パッシングディミニッシュ','sus4 を挟むツーファイブ','iv–♭VII7–I','9th・13th のツーファイブワン','Imaj9–IVmaj9','♭VI–♭VII–I','ドリアンの往復','Lo-fi のマイナー進行','iiø–V–i','エオリアン','マイナーの終止','アンダルシア進行',
  // P12.4-02: appended after the 25, in the list's order.
  'マイナー 2-5-1','裏コードのターンアラウンド','3-6-2-5','マイナーのラインクリシェ','メジャーのラインクリシェ','下降ベース','長3度サイクル','ドミナントの連鎖','平行 maj7','ジャズブルース','マイナーブルース','リズムチェンジ A','ペダルの上で動かす','分数コードのドミナント','リディアン・ヴァンプ','ボサの下降 2-5','モーダルの半音移動','クロマチック・メディアント'];
import {emptyStore,emptyItem,dateKey} from '../src/domain/chordDojo/store';
/** P12.5-02: the two Original Practice cards sit at the end of the list of standard progressions. */
const ORIGINAL_NAMES=['01 Traditional Passing — E°7','02 Modern Passing — Cadd2 on E'];
const plannedNotes=async(page:import('@playwright/test').Page)=>page.evaluate(()=>{const f=JSON.parse(localStorage.getItem('loop-vault:chord-dojo-txt-jazz-v1:data')!);const c=f.today.cursor,t=f.today.tasks[c.taskIndex];return f.today.lesson.targets.find((x:{taskKey:string;keyIndex:number;chordIndex:number;composition:boolean;chord:{notes:number[]}})=>x.taskKey===t.key&&x.keyIndex===c.keyIndex&&x.chordIndex===c.chordIndex&&x.composition===(c.stage==='composition'||t.kind==='composition')).chord.notes as number[];});
const oldTempo=(f:ReturnType<typeof emptyStore>)=>{f.today={date:dateKey(new Date()),tasks:[{kind:'progression',key:'builtin:i-v-vi-iv:1',review:true,roots:[0],seconds:120}],cursor:{taskIndex:0,stage:'tempo',keyIndex:0,chordIndex:0,answerSeen:false,hints:[],tempoResults:[]},finished:false,added:[],matched:0};return f;};
const shapeKey=()=>'preset:basic|close|self|any:quality:maj';
const buildBuiltin=()=>({chords:[{notes:[48,60,64,67]},{notes:[43,59,62,67]},{notes:[45,60,64,67]},{notes:[41,60,64,69]}]});

import {openDojo,play,next,seed,type MidiControl} from './helpers/p12';
test('P12 first theme shapes use three weak keys, feedback, star, pause and resume',async({page})=>{
 await openDojo(page);await page.locator('#main-content').focus();await page.keyboard.press('Enter');await expect(page.getByText('構成を知る',{exact:true})).toBeVisible();await play(page,[48,76,91]);await next(page);await play(page,await plannedNotes(page));await next(page);await expect(page.getByText(/キー 1\/3/)).toBeVisible();const notes=await plannedNotes(page);const wrong=[...notes.slice(0,-1),notes[notes.length-1]+1];await page.evaluate(notes=>(window as typeof window&{__p12Midi:MidiControl}).__p12Midi.emit(notes),wrong);await expect(page.locator('.dojo-result')).toContainText('余分な音');await page.evaluate(notes=>(window as typeof window&{__p12Midi:MidiControl}).__p12Midi.emit(notes,false),wrong);await page.getByRole('button',{name:'もう一度（Enter）'}).click();await play(page,notes);await next(page);await page.getByRole('button',{name:'使いたい',exact:true}).click();await page.getByTestId('dojo-back').click();await page.getByRole('button',{name:/続きから始める/}).click();await expect(page.getByText(/キー 2\/3/)).toBeVisible();await play(page,await plannedNotes(page));await next(page);await play(page,await plannedNotes(page));await next(page);const store=await page.evaluate(()=>JSON.parse(localStorage.getItem('loop-vault:chord-dojo-txt-jazz-v1:data')!));expect(store.shapes[shapeKey()].state).toBe('provisional');expect(store.shapes[shapeKey()].wanted).toBe(true);expect(store.today.tasks).toHaveLength(4);expect(store.today.cursor.taskIndex).toBe(1);
});
test('P12 no MIDI answer then self rating completes shape and preserves provisional ceiling',async({page})=>{
 await openDojo(page,'no-midi');await expect(page.getByText(/MIDI キーボードがつながっていません/)).toBeVisible();await page.getByRole('button',{name:/^始める/}).click();for(let i=0;i<5;i++){if(await page.getByRole('button',{name:'弾けた（Y）'}).count()===0)await page.getByRole('button',{name:'答えを見る（Space）'}).click();await page.getByRole('button',{name:'弾けた（Y）'}).click();await next(page);}while(await page.getByRole('button',{name:'とばす',exact:true}).count())await page.getByRole('button',{name:'とばす',exact:true}).click();await expect(page.getByRole('heading',{name:'今日、自分の語彙に増えたもの'})).toBeVisible();const file=await page.evaluate(()=>JSON.parse(localStorage.getItem('loop-vault:chord-dojo-txt-jazz-v1:data')!));await expect(page.locator('.dojo-finish-summary')).not.toContainText('今回の確認完了');await expect(page.locator('.dojo-finish')).toContainText('I–V–vi–IV');expect(file.shapes[shapeKey()].state).toBe('provisional');expect(file.shapes[shapeKey()].recent.every((r:{self:boolean;sec?:number})=>r.self&&r.sec===undefined)).toBe(true);
});
test('P12 builtin recall hides names, reveals one card after delay and requires retry',async({page})=>{
 await openDojo(page);await page.getByRole('button',{name:'定番の進行',exact:true}).click();await page.locator('.dojo-list .dojo-card').filter({has:page.getByRole('heading',{name:'I–V–vi–IV',exact:true})}).getByRole('button',{name:'これを練習する'}).click();const b=buildBuiltin();for(const c of b.chords){await play(page,c.notes);await next(page);}await page.getByRole('button',{name:'② 覚えて弾くへ（Enter）'}).click();await expect(page.locator('.dojo-chord-cards strong')).toHaveText(['?','?','?','?']);await expect(page.locator('.dojo-result')).toContainText('頭から弾いてください。止まると、そのカードだけ名前が出ます');await expect(page.locator('.dojo-endless-center')).not.toContainText('✓ C');await expect(page.locator('.dojo-endless-center')).not.toContainText('✓ G');await expect(page.locator('.dojo-endless-center')).not.toContainText('Am7');await expect(page.locator('.dojo-endless-center')).not.toContainText('Fmaj7');await expect(page.getByText(/1番目は C です。最初には戻らず続けます/)).toBeVisible({timeout:7000});await expect(page.locator('.dojo-chord-cards strong')).toHaveText(['C','?','?','?']);for(const c of b.chords){await play(page,c.notes);await next(page);}/* P12.5-01: a pass with a hint is not a clear, but it goes straight to another pass: no memorize screen, no retry range. */await expect(page.getByRole('button',{name:'覚えた（Enter）'})).toHaveCount(0);await expect(page.locator('.dojo')).toHaveAttribute('data-dojo-cursor',/:recall:0:0$/);await expect(page.getByTestId('dojo-card-flags')).toHaveText('前回ヒント');await expect(page.getByTestId('dojo-lap-note')).toBeVisible();await expect(page.locator('.dojo-chord-cards strong')).toHaveText(['?','?','?','?']);for(const c of b.chords){await play(page,c.notes);await next(page);}/* P18-01 Stage 2: a clean pass of ② stops at the lap end (くり返す off); Enter goes to the finish screen. */await expect(page.getByTestId('dojo-again-recall')).toBeVisible();await page.getByRole('button',{name:'終わる（Enter）'}).click();await expect(page.getByRole('heading',{name:'今日、自分の語彙に増えたもの'})).toBeVisible();
});
