// Accepted MIDI/UI review regressions. All input and records below are synthetic.
const emit=async(page:import('@playwright/test').Page,notes:number[],on=true)=>page.evaluate(({notes,on})=>(window as typeof window&{__p12Midi:MidiControl}).__p12Midi.emit(notes,on),{notes,on});
const selectInput=async(page:import('@playwright/test').Page,id='p12-synthetic')=>{await page.getByRole('button',{name:'MIDI 設定'}).first().click();await page.getByTestId('midi-panel').getByLabel('使う機器').selectOption(id);await page.keyboard.press('Escape');await expect(page.getByTestId('midi-panel')).toHaveCount(0);await expect(page.locator('.dojo')).toHaveAttribute('data-dojo-midi-mode','midi');};
const recallFile=()=>{const f=emptyStore();f.knownQualities.maj={at:new Date().toISOString(),nextRecallAt:new Date(Date.now()+86400000).toISOString(),recallStep:0};f.today={date:dateKey(new Date()),tasks:[{kind:'shape',key:shapeKey(),quality:'maj',preset:'basic',bass:'self',review:false,roots:[0,5,2],seconds:60}],cursor:{taskIndex:0,stage:'recall',keyIndex:0,chordIndex:0,answerSeen:false,hints:[],tempoResults:[]},finished:false,added:[],matched:0};return f;};
