 await seed(page,recallFile());await openDojo(page,'no-midi');await page.getByRole('button',{name:/^始める/}).click();await expect(page.locator('.dojo')).toHaveAttribute('data-dojo-midi-mode','self');await page.waitForTimeout(700);await page.evaluate(async()=>(window as typeof window&{__p12Midi:MidiControl}).__p12Midi.plug());await selectInput(page);await expect(page.getByText(/MIDI キーボードがつながっていません/)).toHaveCount(0);await emit(page,[48,60,64,67]);await expect(page.locator('.dojo-result')).toContainText('合いました');await page.waitForTimeout(600);await expect(page.locator('.dojo')).toHaveAttribute('data-dojo-cursor','0:recall:0:0');await emit(page,[48,60,64,67],false);await expect(page.locator('.dojo')).toHaveAttribute('data-dojo-cursor','0:recall:1:0');
