test('P12 MIDI notes use sampled piano once, release and stop on list/exit',async({page})=>{
 await page.addInitScript(()=>{const calls={start:0,stop:0};Object.assign(window,{__dojoAudio:calls});const start=AudioBufferSourceNode.prototype.start,stop=AudioBufferSourceNode.prototype.stop;AudioBufferSourceNode.prototype.start=function(...args:Parameters<typeof start>){if(this.buffer&&this.buffer.duration>0.1)calls.start++;return start.apply(this,args);};AudioBufferSourceNode.prototype.stop=function(...args:Parameters<typeof stop>){if(this.buffer&&this.buffer.duration>0.1)calls.stop++;return stop.apply(this,args);};});
 await openDojo(page);await page.getByRole('button',{name:/^始める/}).click();await expect(page.locator('.dojo')).toHaveAttribute('data-dojo-midi-audio','ready');const count=()=>page.evaluate(()=>(window as typeof window&{__dojoAudio:{start:number;stop:number}}).__dojoAudio);const before=await count();await emit(page,[60]);await expect.poll(async()=>(await count()).start-before.start).toBe(1);await page.waitForTimeout(200);expect((await count()).start-before.start).toBe(1);await emit(page,[60],false);await expect.poll(async()=>(await count()).stop-before.stop).toBeGreaterThanOrEqual(1);await page.getByTestId('dojo-back').click();await page.getByRole('button',{name:'型の一覧',exact:true}).click();await expect(page.locator('.dojo')).toHaveAttribute('data-dojo-midi-audio','off');const silent=await count();await emit(page,[62]);await page.waitForTimeout(100);expect((await count()).start).toBe(silent.start);await page.getByTestId('dojo-back').click();await expect(page.locator('.dojo')).toHaveAttribute('data-dojo-midi-audio','ready');const held=await count();await page.waitForTimeout(100);expect((await count()).start).toBe(held.start);await emit(page,[62],false);await emit(page,[64]);await expect.poll(async()=>(await count()).start-held.start).toBe(1);await page.locator('[data-nav="vault"]').click();await expect.poll(async()=>(await count()).stop-held.stop).toBeGreaterThanOrEqual(1);
});

