 await page.evaluate(()=>(window as typeof window&{__p12Midi:ConnectionControl}).__p12Midi.resumeOpen(true));await expect(page.getByRole('alert')).toContainText('MIDI 接続でエラーが起きました。合成接続エラー');await expect(page.locator('.lv-midi-chip')).toHaveAttribute('data-midi-kind','error');
