async function assertPracticeViewport(page:import('@playwright/test').Page){
 const geometry=await page.locator('.dojo').evaluate(root=>{
  const main=document.querySelector('#main-content')!,center=root.querySelector('.dojo-center')!,keyboard=root.querySelector('.dojo-keyboard')!,svg=keyboard.querySelector('svg')!;
  const viewport=main.getBoundingClientRect(),task=center.getBoundingClientRect(),keys=svg.getBoundingClientRect();
  const actions=[...root.querySelectorAll('.dojo-center .dojo-actions button')].filter(e=>e.getClientRects().length>0).map(e=>{const r=e.getBoundingClientRect();return {top:r.top,bottom:r.bottom,left:r.left,right:r.right};});
  return {mainTop:viewport.top,mainBottom:viewport.bottom,mainScroll:main.scrollHeight-main.clientHeight,mainScrollTop:main.scrollTop,centerTop:task.top,centerBottom:task.bottom,centerScroll:center.scrollHeight-center.clientHeight,keyTop:keys.top,keyBottom:keys.bottom,keyHeight:keys.height,keyCount:keyboard.querySelectorAll('[data-midi-note]').length,overflow:root.scrollWidth-root.clientWidth,actions};
 });
 expect(geometry.mainScrollTop).toBe(0);expect(geometry.mainScroll).toBeLessThanOrEqual(1);expect(geometry.centerScroll).toBeLessThanOrEqual(1);expect(geometry.keyCount).toBeGreaterThanOrEqual(49);expect(geometry.keyHeight).toBe(128);expect(geometry.keyTop).toBeGreaterThanOrEqual(geometry.mainTop);expect(geometry.keyBottom).toBeLessThanOrEqual(geometry.mainBottom);expect(geometry.overflow).toBe(0);
 for(const button of geometry.actions){expect(button.top).toBeGreaterThanOrEqual(geometry.centerTop);expect(button.bottom).toBeLessThanOrEqual(geometry.centerBottom);}
 await expect(page.locator('.dojo-keyboard svg')).toBeInViewport({ratio:1});
 for(const button of await page.locator('.dojo-center .dojo-actions button').all())if(await button.isVisible())await expect(button).toBeInViewport({ratio:1});
 return await page.locator('.dojo-keyboard').boundingBox();
}
for(const [width,height] of [[1440,900],[1366,768],[1280,720]])for(const fixture of ['normal','theme'])test(`P12 initial viewport ${width}x${height} ${fixture} keeps task actions score and input keyboard visible`,async({page})=>{
 await page.setViewportSize({width,height});await page.goto(`/?p12=no-midi${fixture==='theme'?'&p104=theme':''}`);await page.locator('[data-nav="chord-dojo"]').click();await page.getByTestId('practice-start').click();
 const baseline=await assertPracticeViewport(page);await expect(page.getByTestId('dojo-score')).toHaveAttribute('data-score-visible','true');
 const advanceManual=async()=>{await page.getByRole('button',{name:'弾けた（Y）'}).click();await next(page);};
 await advanceManual();await assertPracticeViewport(page);await advanceManual();await assertPracticeViewport(page);
 await expect(page.getByTestId('dojo-score')).toHaveAttribute('data-score-visible','false');await expect(page.locator('[data-answer-marker],[data-score-midi]')).toHaveCount(0);
 await page.evaluate(async()=>(window as typeof window&{__p12Midi:MidiControl}).__p12Midi.connect());await emit(page,[60]);await expect(page.locator('.dojo-keyboard [data-midi-note="60"]')).toHaveAttribute('data-visual-state','held-correct');await expect(page.locator('.dojo-keyboard [data-midi-note="60"]>rect')).toHaveAttribute('fill','#8fb7ff');await expect(page.locator('[data-answer-marker],[data-score-midi]')).toHaveCount(0);await assertPracticeViewport(page);await emit(page,[60],false);
 await page.getByRole('button',{name:'もう一度見る'}).click();const after=await assertPracticeViewport(page);expect(after?.y).toBe(baseline?.y);expect(after?.height).toBe(baseline?.height);await expect(page.locator('[data-score-midi]').first()).toBeInViewport({ratio:1});
 const notes=await plannedNotes(page);await emit(page,[...notes.slice(0,-1),notes[notes.length-1]+1]);await expect(page.locator('.dojo-result')).toContainText('余分な音');await assertPracticeViewport(page);
});
